begin;
create table wm.delivery_templates(
 catalog_id text not null,variant text not null,version text not null,template jsonb not null,
 primary key(catalog_id,variant,version)
);
create table wm.delivery_runs(
 organization_id uuid not null,id uuid not null default gen_random_uuid(),engagement_id uuid not null,request_id uuid not null,agreement_id uuid not null,
 period_key text not null,template jsonb not null,status text not null default 'active' check(status in ('active','complete')),
 completed_revision_id uuid,completed_at timestamptz,created_by uuid not null,created_at timestamptz not null default now(),version bigint not null default 1,
 primary key(organization_id,id),unique(organization_id,request_id,period_key),
 foreign key(organization_id,engagement_id,request_id) references wm.requests(organization_id,engagement_id,id),
 foreign key(organization_id,agreement_id) references wm.agreements(organization_id,id),
 foreign key(organization_id,request_id,completed_revision_id) references wm.revisions(organization_id,request_id,id)
);
create table wm.delivery_observations(
 organization_id uuid not null,id uuid not null default gen_random_uuid(),run_id uuid not null,step_key text not null,
 outcome text not null check(outcome in ('passed','failed','unknown')),evidence text not null,observed_at timestamptz not null,recorded_by uuid not null,
 revision_id uuid,operation_id uuid,report_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now(),
 primary key(organization_id,id),foreign key(organization_id,run_id) references wm.delivery_runs(organization_id,id),
 foreign key(organization_id,revision_id) references wm.revisions(organization_id,id),foreign key(organization_id,operation_id) references wm.operations(organization_id,id),
 foreign key(organization_id,report_id) references wm.reports(organization_id,id)
);
create table wm.revision_facts(
 organization_id uuid not null,revision_id uuid not null,fact_id uuid not null,
 primary key(organization_id,revision_id,fact_id),foreign key(organization_id,revision_id) references wm.revisions(organization_id,id),
 foreign key(organization_id,fact_id) references wm.business_facts(organization_id,id)
);
create table wm.fact_impacts(
 organization_id uuid not null,id uuid not null default gen_random_uuid(),revision_id uuid not null,old_fact_id uuid not null,new_fact_id uuid not null,created_at timestamptz not null default now(),
 primary key(organization_id,id),unique(organization_id,revision_id,new_fact_id),foreign key(organization_id,revision_id) references wm.revisions(organization_id,id),
 foreign key(organization_id,old_fact_id) references wm.business_facts(organization_id,id),foreign key(organization_id,new_fact_id) references wm.business_facts(organization_id,id)
);
alter table wm.delivery_templates enable row level security;
alter table wm.delivery_runs enable row level security;
alter table wm.delivery_observations enable row level security;
alter table wm.revision_facts enable row level security;
alter table wm.fact_impacts enable row level security;
revoke all on wm.delivery_templates,wm.delivery_runs,wm.delivery_observations,wm.revision_facts,wm.fact_impacts from public,anon,authenticated,service_role;
create function wm.delivery_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Delivery evidence is immutable';end $$;
create trigger immutable_delivery_observation before update or delete on wm.delivery_observations for each row execute function wm.delivery_immutable();
create trigger immutable_revision_facts before update or delete on wm.revision_facts for each row execute function wm.delivery_immutable();
create trigger immutable_fact_impacts before update or delete on wm.fact_impacts for each row execute function wm.delivery_immutable();
create function wm.revision_sources_current(org uuid,revision uuid) returns boolean language sql volatile security definer set search_path='' as $$
 select not exists(select 1 from wm.fact_impacts where organization_id=org and revision_id=revision)
 and not exists(select 1 from wm.revision_facts rf join wm.business_facts f on f.organization_id=rf.organization_id and f.id=rf.fact_id
 left join lateral (select n.* from wm.business_facts n where n.organization_id=org and n.key=f.key and not exists(select 1 from wm.business_facts newer where newer.organization_id=org and newer.supersedes_id=n.id) order by n.created_at desc,n.id desc limit 1) latest on true
 where rf.organization_id=org and rf.revision_id=revision and (latest.id is null or latest.value is distinct from f.value or latest.valid_until<=clock_timestamp()))
$$;
create function wm.delivery_approved(org uuid,request uuid,revision uuid) returns boolean language sql volatile security definer set search_path='' as $$
 select exists(select 1 from wm.requests r join wm.revisions v on v.organization_id=r.organization_id and v.request_id=r.id and v.id=r.current_revision_id
 where r.organization_id=org and r.id=request and v.id=revision and v.kind<>'agreement' and r.state in ('approved','executing','verifying','complete')
 and exists(select 1 from wm.decisions d join wm.engagement_authorities a on a.organization_id=d.organization_id and a.id=d.authority_id join wm.memberships m on m.organization_id=d.organization_id and m.user_id=d.actor_id
 where d.organization_id=org and d.revision_id=v.id and d.id=(select last.id from wm.decisions last where last.organization_id=org and last.revision_id=v.id order by last.created_at desc,last.id desc limit 1)
 and d.decision='approve' and a.revoked_at is null and a.starts_at<=clock_timestamp() and a.ends_at>clock_timestamp() and a.version=d.authority_version and m.status='active' and m.revoked_at is null and m.role<>'viewer')
 and wm.revision_sources_current(org,v.id))
$$;
create function wm.fact_changed() returns trigger language plpgsql security definer set search_path='' as $$
declare r wm.requests;
begin
 if new.supersedes_id is null then return new;end if;
 if exists(select 1 from wm.business_facts f where f.organization_id=new.organization_id and f.id=new.supersedes_id and f.value=new.value) then return new;end if;
 with recursive ancestors as (
  select f.id,f.supersedes_id from wm.business_facts f where f.organization_id=new.organization_id and f.id=new.supersedes_id
  union all select f.id,f.supersedes_id from wm.business_facts f join ancestors a on a.supersedes_id=f.id where f.organization_id=new.organization_id
 ) insert into wm.fact_impacts(organization_id,revision_id,old_fact_id,new_fact_id)
 select new.organization_id,rf.revision_id,rf.fact_id,new.id from wm.revision_facts rf join ancestors a on a.id=rf.fact_id
 where rf.organization_id=new.organization_id on conflict(organization_id,revision_id,new_fact_id) do nothing;
 for r in select q.* from wm.requests q where q.organization_id=new.organization_id and exists(select 1 from wm.fact_impacts i where i.organization_id=q.organization_id and i.revision_id=q.current_revision_id and i.new_fact_id=new.id) loop
  update wm.requests set state='changes_requested',version=version+1,waiting_reason='A source fact changed. Prepare and approve a new version.',updated_at=now() where organization_id=new.organization_id and id=r.id;
  update wm.operations set state='cancelled',last_error_code='source_fact_changed',version=version+1 where organization_id=new.organization_id and request_id=r.id and positive_effect and state='pending';
  update wm.outbox_jobs j set state='cancelled' from wm.operations o where o.organization_id=new.organization_id and o.id=j.operation_id and j.organization_id=o.organization_id and o.state='cancelled' and j.state in ('pending','leased');
  if exists(select 1 from wm.provider_scopes where organization_id=new.organization_id and engagement_id=r.engagement_id and provider in ('google_ads','meta_ads','microsoft_ads','tiktok_ads','linkedin_ads')) then perform wm.request_stop(new.organization_id,r.engagement_id,'Approved source fact changed; review required',auth.uid());end if;
 end loop;
 if exists(select 1 from wm.fact_impacts where organization_id=new.organization_id and new_fact_id=new.id) then
  update wm.tenant_guards set authority_version=authority_version+1 where organization_id=new.organization_id;
  perform wm.critical(new.organization_id,'fact.impact',new.id,jsonb_build_object('old_fact',new.supersedes_id,'new_fact',new.id));
 end if;
 return new;
end $$;
create trigger fact_change_impacts after insert on wm.business_facts for each row execute function wm.fact_changed();
create function wm.delivery_report_current(org uuid,request uuid,period text,report uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from wm.reports r where r.organization_id=org and r.id=report and r.request_id=request and r.period_key=period and r.status='published'
 and cardinality(r.source_snapshot_ids)>0 and not exists(select 1 from unnest(r.source_snapshot_ids) sid left join wm.metric_snapshots s on s.organization_id=org and s.id=sid left join wm.import_runs i on i.organization_id=s.organization_id and i.id=s.import_run_id where i.id is null or i.status<>'promoted'))
$$;
-- Expiry can happen without a new fact command. Check sources at approval, preparation and dispatch too.
alter function public.wm_decision_record(uuid,jsonb,text) rename to wm_decision_before_delivery;
revoke all on function public.wm_decision_before_delivery(uuid,jsonb,text) from public,anon,authenticated,service_role;
create function public.wm_decision_record(p_org uuid,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
begin
 perform wm.require_access(p_org,'write');
 if p_input->>'decision'='approve' and not wm.revision_sources_current(p_org,(p_input->>'revision_id')::uuid) then raise exception 'Source facts changed or expired; prepare a current revision' using errcode='40001';end if;
 return public.wm_decision_before_delivery(p_org,p_input,p_key);
end $$;
alter function public.wm_operation_prepare(uuid,jsonb,text) rename to wm_operation_prepare_before_delivery;
revoke all on function public.wm_operation_prepare_before_delivery(uuid,jsonb,text) from public,anon,authenticated,service_role;
create function public.wm_operation_prepare(p_org uuid,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
begin
 perform wm.require_access(p_org,case when wm.ad_provider(p_input->>'kind') is not null then 'ads' else 'delivery' end);
 if not wm.revision_sources_current(p_org,(p_input->>'revision_id')::uuid) then raise exception 'Source facts changed or expired; prepare a current revision' using errcode='40001';end if;
 return public.wm_operation_prepare_before_delivery(p_org,p_input,p_key);
end $$;
alter function public.wm_attempt_begin(uuid,uuid,bigint,text) rename to wm_attempt_begin_before_delivery;
revoke all on function public.wm_attempt_begin_before_delivery(uuid,uuid,bigint,text) from public,anon,authenticated,service_role;
create function public.wm_attempt_begin(p_org uuid,p_job uuid,p_lease_generation bigint,p_external_generation text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare op wm.operations;
begin
 perform wm.require_machine();perform 1 from wm.tenant_guards where organization_id=p_org for update;
 select o.* into op from wm.operations o join wm.outbox_jobs j on j.organization_id=o.organization_id and j.operation_id=o.id where j.organization_id=p_org and j.id=p_job;
 if op.positive_effect and op.revision_id is not null and not wm.revision_sources_current(p_org,op.revision_id) then raise exception 'Source facts changed or expired; prepare a current revision' using errcode='40001';end if;
 return public.wm_attempt_begin_before_delivery(p_org,p_job,p_lease_generation,p_external_generation);
end $$;
create function public.wm_delivery_command(p_org uuid,p_command text,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb; run wm.delivery_runs; a wm.agreements; req wm.requests; rev wm.revisions; cat wm.catalog_snapshots; tpl jsonb; step jsonb; obs wm.delivery_observations;
 rid uuid; ver bigint:=1; operation wm.operations; observed timestamptz; d jsonb; k text; f uuid;
begin
 perform wm.require_access(p_org,'delivery');result:=wm.prior_command(p_org,p_command,p_key,p_input);if result is not null then return result;end if;
 if p_command='delivery.start' then
  perform wm.check_input(p_input,array['request_id','agreement_id','period_key'],array['request_id','agreement_id','period_key']);
  select * into req from wm.requests where organization_id=p_org and id=(p_input->>'request_id')::uuid for update;
  if not found or req.accepted_scope is null then raise exception 'Accept the work scope first' using errcode='42501';end if;
  if exists(select 1 from wm.revisions where organization_id=p_org and id=req.current_revision_id and kind='agreement') then raise exception 'Choose delivery work, not the agreement itself' using errcode='22023';end if;
  select * into a from wm.agreements where organization_id=p_org and engagement_id=req.engagement_id and id=(p_input->>'agreement_id')::uuid and status='accepted';
  if not found then raise exception 'Choose an accepted agreement for this service' using errcode='42501';end if;
  if exists(select 1 from wm.engagements where organization_id=p_org and id=req.engagement_id and service_state in ('ending','closed')) then raise exception 'Service is closing' using errcode='42501';end if;
  select * into cat from wm.catalog_snapshots where organization_id=p_org and id=a.catalog_snapshot_id;
  select template into tpl from wm.delivery_templates where catalog_id=cat.catalog_id and variant=coalesce(cat.snapshot->>'variant','standard') order by version desc limit 1;
  if tpl is null then raise exception 'This accepted catalog needs a delivery template' using errcode='22023';end if;
  perform wm.require_text(p_input->>'period_key','delivery period',100);
  if tpl->>'recurring'='true' and p_input->>'period_key' !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Use the calendar month YYYY-MM for recurring work' using errcode='22023';end if;
  insert into wm.delivery_runs(organization_id,engagement_id,request_id,agreement_id,period_key,template,created_by) values(p_org,req.engagement_id,req.id,a.id,p_input->>'period_key',tpl,auth.uid()) returning id into rid;
 elsif p_command='delivery.facts' then
  perform wm.check_input(p_input,array['revision_id','fact_ids'],array['revision_id','fact_ids']);
  select * into rev from wm.revisions where organization_id=p_org and id=(p_input->>'revision_id')::uuid;
  select * into req from wm.requests where organization_id=p_org and id=rev.request_id;
  if rev.id is null or req.current_revision_id is distinct from rev.id or req.state<>'in_review' or exists(select 1 from wm.decisions where organization_id=p_org and revision_id=rev.id) then raise exception 'Link source facts before the first decision on the current revision' using errcode='42501';end if;
  if jsonb_typeof(p_input->'fact_ids')<>'array' or jsonb_array_length(p_input->'fact_ids') not between 1 and 100 then raise exception 'Select current source facts' using errcode='22023';end if;
  for f in select value::uuid from jsonb_array_elements_text(p_input->'fact_ids') loop
   if not exists(select 1 from wm.business_facts x where organization_id=p_org and id=f and (valid_until is null or valid_until>now()) and not exists(select 1 from wm.business_facts n where n.organization_id=p_org and n.supersedes_id=x.id)) then raise exception 'Source fact is unavailable or superseded' using errcode='40001';end if;
   insert into wm.revision_facts values(p_org,rev.id,f) on conflict do nothing;
  end loop;rid:=rev.id;
 elsif p_command in ('delivery.observe','delivery.complete') then
  select * into run from wm.delivery_runs where organization_id=p_org and id=(p_input->>'id')::uuid for update;
  if not found then raise exception 'Delivery unavailable' using errcode='42501';end if;
  perform wm.check_version(run.version,(p_input->>'expected_version')::bigint);
  if run.status<>'active' then raise exception 'Delivery already completed; start separately accepted corrective work' using errcode='22023';end if;
  select * into req from wm.requests where organization_id=p_org and id=run.request_id;
  if p_command='delivery.observe' then
   perform wm.check_input(p_input,array['id','expected_version','step_key','outcome','evidence','observed_at','revision_id','operation_id','report_id','details'],array['id','expected_version','step_key','outcome','evidence','observed_at']);
   select value into step from jsonb_array_elements(run.template->'steps') where value->>'key'=p_input->>'step_key';
   if step is null or p_input->>'outcome' not in ('passed','failed','unknown') then raise exception 'Choose a delivery check and actual outcome' using errcode='22023';end if;
   observed:=(p_input->>'observed_at')::timestamptz;
   if not isfinite(observed) or observed>now()+interval '5 minutes' or observed<run.created_at-interval '30 days' then raise exception 'Check the evidence date' using errcode='22023';end if;
   perform wm.require_text(p_input->>'evidence','evidence',8000);d:=coalesce(p_input->'details','{}');
   if jsonb_typeof(d)<>'object' or octet_length(d::text)>12000 then raise exception 'Check the delivery details' using errcode='22023';end if;
   if p_input->>'revision_id' is not null and not exists(select 1 from wm.revisions where organization_id=p_org and request_id=req.id and id=(p_input->>'revision_id')::uuid) then raise exception 'Revision belongs to different work' using errcode='42501';end if;
   if p_input->>'operation_id' is not null and not exists(select 1 from wm.operations where organization_id=p_org and request_id=req.id and id=(p_input->>'operation_id')::uuid) then raise exception 'Operation belongs to different work' using errcode='42501';end if;
   if p_input->>'report_id' is not null and not exists(select 1 from wm.reports where organization_id=p_org and engagement_id=run.engagement_id and id=(p_input->>'report_id')::uuid) then raise exception 'Report belongs to different service' using errcode='42501';end if;
   if p_input->>'outcome'='passed' then
    if req.current_revision_id is null or req.current_revision_id is distinct from (p_input->>'revision_id')::uuid then raise exception 'Record passing checks against the current work revision' using errcode='40001';end if;
    if step->>'gate' in ('approval','publication','handoff') and not wm.delivery_approved(p_org,req.id,(p_input->>'revision_id')::uuid) then raise exception 'Exact current approved revision required' using errcode='42501';end if;
    if step->>'gate'='publication' then
     select * into operation from wm.operations where organization_id=p_org and id=(p_input->>'operation_id')::uuid and request_id=req.id and revision_id=(p_input->>'revision_id')::uuid and state='verified' and positive_effect and (kind='website_publish' or kind ~ '^(google|meta|microsoft|tiktok|linkedin)_(enable|update)$');
     if not found then raise exception 'Verified provider publication of the exact approved revision required' using errcode='42501';end if;
    end if;
    if step->>'gate'='report' and not wm.delivery_report_current(p_org,req.id,run.period_key,(p_input->>'report_id')::uuid) then raise exception 'A published reviewed report for this work and period, with current source evidence, is required' using errcode='42501';end if;
    if step->>'gate'='handoff' then
     foreach k in array array['editable_source','owner_access','licenses','recovery','correction_period'] loop perform wm.require_text(d->>k,k,2000);end loop;
    end if;
    if step->>'key' in ('journey','care_journey') then
     foreach k in array array['test_authorization','submission_receipt','destination_receipt'] loop perform wm.require_text(d->>k,k,2000);end loop;
    end if;
    if step->>'key'='search_observation' then
     perform wm.require_text(d->>'published_url','published URL',2000);
     if d->>'indexing_state' is null or d->>'indexing_state' not in ('unknown','not_indexed','indexed') then raise exception 'Record indexing separately from publication' using errcode='22023';end if;
     if d->>'indexing_state'<>'unknown' then perform wm.require_text(d->>'indexing_evidence','dated Search Console observation',2000);end if;
    end if;
   end if;
   insert into wm.delivery_observations(organization_id,run_id,step_key,outcome,evidence,observed_at,recorded_by,revision_id,operation_id,report_id,details)
    values(p_org,run.id,step->>'key',p_input->>'outcome',p_input->>'evidence',observed,auth.uid(),(p_input->>'revision_id')::uuid,(p_input->>'operation_id')::uuid,(p_input->>'report_id')::uuid,d);
  else
   perform wm.check_input(p_input,array['id','expected_version','revision_id'],array['id','expected_version','revision_id']);
   if not wm.delivery_approved(p_org,req.id,(p_input->>'revision_id')::uuid) then raise exception 'Exact current approved revision required' using errcode='42501';end if;
   for step in select value from jsonb_array_elements(run.template->'steps') loop
    select * into obs from wm.delivery_observations where organization_id=p_org and run_id=run.id and step_key=step->>'key' order by created_at desc,id desc limit 1;
    if obs.id is null or obs.outcome<>'passed' then raise exception 'Every required delivery check needs passed evidence: %',step->>'title' using errcode='42501';end if;
    if obs.revision_id is distinct from (p_input->>'revision_id')::uuid then raise exception 'Delivery evidence belongs to an older version' using errcode='40001';end if;
    if step->>'gate'='report' and not wm.delivery_report_current(p_org,req.id,run.period_key,obs.report_id) then raise exception 'Report evidence has been superseded or does not match this work and period' using errcode='40001';end if;
   end loop;
   if exists(select 1 from wm.operations where organization_id=p_org and request_id=req.id and state not in ('verified','cancelled')) then raise exception 'Resolve pending, failed or uncertain operations before completion' using errcode='42501';end if;
   if exists(select 1 from wm.dependencies dep join wm.requests b on b.organization_id=dep.organization_id and b.id=dep.blocking_request_id where dep.organization_id=p_org and dep.request_id=req.id and b.state<>'complete') then raise exception 'Complete blocking work first' using errcode='42501';end if;
   update wm.delivery_runs set status='complete',completed_revision_id=(p_input->>'revision_id')::uuid,completed_at=now() where organization_id=p_org and id=run.id;
   update wm.requests set state='complete',version=version+1,updated_at=now() where organization_id=p_org and id=req.id;
   perform wm.critical(p_org,'delivery.completed',run.id,jsonb_build_object('request',req.id,'revision',p_input->>'revision_id','agreement',run.agreement_id));
  end if;
  update wm.delivery_runs set version=version+1 where organization_id=p_org and id=run.id returning id,version into rid,ver;
 else raise exception 'Unknown delivery command' using errcode='22023';end if;
 return wm.finish_command(p_org,p_command,p_key,p_input,jsonb_build_object('id',rid,'version',ver),rid);
end $$;
-- Completion uses the catalog-specific evidence gate, including work without an external API effect.
alter function public.wm_service_command(uuid,text,jsonb,text) rename to wm_service_command_before_delivery;
revoke all on function public.wm_service_command_before_delivery(uuid,text,jsonb,text) from public,anon,authenticated,service_role;
create function public.wm_service_command(p_org uuid,p_command text,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
begin
 if p_command='request.progress' and p_input->>'state'='complete' then raise exception 'Use the delivery plan to verify every required completion check' using errcode='42501';end if;
 return public.wm_service_command_before_delivery(p_org,p_command,p_input,p_key);
end $$;
alter function public.wm_workspace(uuid) rename to wm_workspace_before_delivery;
revoke all on function public.wm_workspace_before_delivery(uuid) from public,anon,authenticated,service_role;
create function public.wm_workspace(p_org uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare result jsonb;
begin
 result:=public.wm_workspace_before_delivery(p_org);
 return result||jsonb_build_object('delivery_runs',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from wm.delivery_runs x where organization_id=p_org),
 'delivery_observations',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc,id desc),'[]') from wm.delivery_observations x where organization_id=p_org),
 'revision_facts',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from wm.revision_facts x where organization_id=p_org),
 'fact_impacts',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from wm.fact_impacts x where organization_id=p_org));
end $$;
revoke all on function wm.delivery_immutable(),wm.delivery_report_current(uuid,uuid,text,uuid),wm.revision_sources_current(uuid,uuid),wm.delivery_approved(uuid,uuid,uuid),wm.fact_changed() from public,anon,authenticated,service_role;
